289	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
290	            }
291	        }
292	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
293	    }
294	
295	    /**
296	     * Counts how many existing owners share the given first and last name, compared
297	     * case-insensitively, at the moment before the new owner is persisted. The result is
298	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
299	     * stood when the owner was created rather than being recomputed on later reads.
300	     *
301	     * @param firstName the first name of the owner being created
302	     * @param lastName the last name of the owner being created
303	     * @return the number of pre-existing owners with the same first and last name
304	     */
305	    private int countNamesakes(String firstName, String lastName) {
306	        String first = firstName == null ? "" : firstName;
307	        String last = lastName == null ? "" : lastName;
308	        return (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
310	                && last.equalsIgnoreCase(existing.getLastName()))
311	            .count();
312	    }
313	
314	    /**
315	     * Builds the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'} where
316	     * {@code REGION} is the region code derived from the owner's postcode (see {@link #deriveRegion})
317	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
318	     * normalized telephone concatenated with the last name. For example an owner in the NSW postcode
319	     * range gets a code such as {@code 'NSW-3F2A1B9C'}.
320	     *
321	     * <p>When the computed code collides with an existing owner's customer code, it is de-duplicated
322	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result
323	     * unique across all existing owners' customer codes. The de-duplicated code is what gets assigned.
324	     *
325	     * @param owner the owner being created, whose postcode, city and last name feed the code
326	     * @param normalizedTelephone the owner's E.164-normalized telephone
327	     * @return the assigned customer code, de-duplicated against existing owners if necessary
328	     */
329	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
330	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
331	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
332	        String hash8 = sha256Hex8(normalizedTelephone + lastName);
333	        String baseCode = region + "-" + hash8;
334	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
335	            .map(Owner::getCustomerCode)
336	            .filter(code -> code != null)
337	            .collect(java.util.stream.Collectors.toSet());
338	        if (!existingCodes.contains(baseCode)) {
339	            return baseCode;
340	        }
341	        int n = 2;
342	        while (existingCodes.contains(baseCode + "-" + n)) {
343	            n++;
344	        }
345	        return baseCode + "-" + n;
346	    }
347	
348	    /**
349	     * Derives an owner's region code, preferring the postcode: the region whose {@link #REGION_POSTCODES}
350	     * range contains the (4-digit) postcode is returned, falling back to the fixed {@link #CITY_REGION}
351	     * city table when the postcode is absent or in no known range, and finally to {@code "UNKNOWN"}.
352	     *
353	     * @param postcode the owner's postcode, may be {@code null}
354	     * @param city the owner's city, used to resolve the region when the postcode does not
355	     * @return the canonical region string, or {@code "UNKNOWN"} when neither source resolves a region
356	     */
357	    private String deriveRegion(String postcode, String city) {
358	        if (postcode != null) {
359	            try {
360	                int value = Integer.parseInt(postcode.trim());
361	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
362	                    int[] range = entry.getValue();
363	                    if (value >= range[0] && value <= range[1]) {
364	                        return entry.getKey();
365	                    }
366	                }
367	            } catch (NumberFormatException ex) {
368	                // Not a numeric postcode; fall back to the city table below.
369	            }
370	        }
371	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
372	    }
373	
374	    /**
375	     * Computes the first 8 upper-case hex characters (the first 4 bytes) of the SHA-256 digest of the
376	     * given input's UTF-8 bytes.
377	     *
378	     * @param input the string to hash
379	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
380	     */
381	    private String sha256Hex8(String input) {
382	        try {
383	            byte[] digest = MessageDigest.getInstance("SHA-256")
384	                .digest(input.getBytes(StandardCharsets.UTF_8));
385	            StringBuilder hex = new StringBuilder();
386	            for (int i = 0; i < 4; i++) {
387	                hex.append(String.format("%02X", digest[i]));
388	            }
389	            return hex.toString();
390	        } catch (NoSuchAlgorithmException ex) {
391	            throw new IllegalStateException("SHA-256 not available", ex);
392	        }
393	    }
394	
395	    /**
396	     * Rejects an owner payload that is missing or blank in any of the required fields
397	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
398	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
399	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
400	     * guard enforces the rule uniformly for every required field.
401	     *
402	     * @param ownerFieldsDto the submitted owner payload
403	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
404	     */
405	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
406	        List<String> invalidFields = new ArrayList<>();
407	        if (isBlank(ownerFieldsDto.getFirstName())) {
408	            invalidFields.add("firstName");
409	        }
410	        if (isBlank(ownerFieldsDto.getLastName())) {
411	            invalidFields.add("lastName");
412	        }
413	        if (isBlank(ownerFieldsDto.getAddressLine1())
414	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
415	            invalidFields.add("address");
416	        }
417	        if (isBlank(ownerFieldsDto.getCity())) {
418	            invalidFields.add("city");
419	        }
420	        if (isBlank(ownerFieldsDto.getTelephone())) {
421	            invalidFields.add("telephone");
422	        }
423	        if (!invalidFields.isEmpty()) {
424	            throw new InvalidOwnerFieldsException(invalidFields);
425	        }
426	    }
427	
428	    private boolean isBlank(String value) {
429	        return value == null || value.isBlank();
430	    }
431	
432	    /**
433	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
434	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
435	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
436	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
437	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
438	     * and returned exactly as given.
439	     *
440	     * @param postcode the submitted postcode, may be {@code null} when absent
441	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
442	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
443	     */
444	    private void validatePostcode(String postcode, String city) {
445	        if (postcode == null) {
446	            return;
447	        }
448	        if (!postcode.matches("[0-9]{4}")) {
449	            throw new InvalidOwnerFieldsException(List.of("postcode"));
450	        }
451	        String region = city == null ? null : CITY_REGION.get(city);
452	        if (region == null) {
453	            return;
454	        }
455	        int[] range = REGION_POSTCODES.get(region);
456	        int value = Integer.parseInt(postcode);
457	        if (value < range[0] || value > range[1]) {
458	            throw new InvalidOwnerFieldsException(List.of("postcode"));
459	        }
460	    }
461	
462	    /**
463	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
464	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
465	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
466	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
467	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
468	     *
469	     * @param telephone the raw telephone value from the submitted owner payload
470	     * @return the normalized E.164 telephone number
471	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
472	     */
473	    private String normalizeTelephone(String telephone) {
474	        String raw = telephone == null ? "" : telephone.strip();
475	        boolean hasCountryCode = raw.startsWith("+");
476	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
477	        String digits;
478	        if (hasCountryCode) {
479	            digits = cleaned.substring(1);
480	        } else {
481	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
482	            digits = "61" + national;
483	        }
484	        if (!digits.matches("[0-9]{8,15}")) {
485	            throw new InvalidOwnerFieldsException(List.of("telephone"));
486	        }
487	        validateNationalNumberLength(digits);
488	        return "+" + digits;
489	    }
490	
491	    /**
492	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
493	     * country calling code) has the exact length required for that country. The country code is matched
494	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
495	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
496	     *
497	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
498	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
499	     */
500	    private void validateNationalNumberLength(String digits) {
501	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
502	            String countryCode = entry.getKey();
503	            if (digits.startsWith(countryCode)) {
504	                int nationalLength = digits.length() - countryCode.length();
505	                if (nationalLength != entry.getValue()) {
506	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
507	                }
508	                return;
509	            }
510	        }
511	    }
512	
513	    /**
514	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
515	     * returning {@code null} when the value cannot form a valid E.164 number.
516	     *
517	     * @param telephone an existing owner's stored telephone value
518	     * @return the E.164 form, or {@code null} if it cannot be normalized
519	     */
520	    private String toE164OrNull(String telephone) {
521	        try {
522	            return normalizeTelephone(telephone);
523	        } catch (InvalidOwnerFieldsException ex) {
524	            return null;
525	        }
526	    }
527	
528	    /**
529	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
530	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
531	     * accepted value is trimmed and lower-cased before it is stored and returned.
532	     *
533	     * @param email the raw email value from the submitted owner payload, may be {@code null}
534	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
535	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
536	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
537	     */
538	    private String normalizeEmail(String email) {
539	        if (email == null) {
540	            return null;
541	        }
542	        String trimmed = email.strip();
543	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
544	            throw new InvalidOwnerFieldsException(List.of("email"));
545	        }
546	        String normalized = trimmed.toLowerCase(Locale.ROOT);
547	        String domain = normalized.substring(normalized.indexOf('@') + 1);
548	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
549	            throw new InvalidOwnerFieldsException(List.of("email"));
550	        }
551	        return normalized;
552	    }
553	
554	    /**
555	     * Rejects creating an owner that would be a second member of an existing household. The household
556	     * is keyed on {@code (lastName, postcode)} through the deterministic {@link #householdId}, so any
557	     * existing owner carrying the same {@code householdId} makes the owner being created a household
558	     * duplicate. Such an owner is rejected with a 409, <em>unless</em> the request opts into
559	     * {@code sharesHousehold}: a declared household member deliberately bypasses this block and is
560	     * created as an additional member of the household.
561	     *
562	     * @param owner the owner being created, whose computed household id is matched
563	     * @param sharesHousehold whether the request declared the owner a shared-household member
564	     * @throws DuplicateOwnerIdentityException if another owner already belongs to the same household
565	     */
566	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
567	        if (sharesHousehold) {
568	            return;
569	        }
570	        String householdId = owner.getHouseholdId();
571	        boolean duplicate = householdId != null && this.clinicService.findAllOwners().stream()
572	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
573	        if (duplicate) {
574	            throw new DuplicateOwnerIdentityException(householdId);
575	        }
576	    }
577	
578	    /**
579	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
580	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
581	     * owner that is not a hard duplicate but shares an existing owner's last name (compared
582	     * case-insensitively, see {@link #normalizeForComparison}) and postcode while carrying a <em>different</em>
583	     * telephone. When such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
584	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
585	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
586	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
587	     *
588	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the household
589	     * duplicate block) is never a <em>suspected</em> duplicate: it is knowingly created as another member
590	     * of the household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
591	     * {@code null} without consulting the existing population.
592	     *
593	     * @param owner the owner being created, whose last name and postcode are matched
594	     * @param normalizedTelephone the E.164 telephone of the owner being created
595	     * @param sharesHousehold whether the request declared the owner a shared-household member
596	     */
597	    private void assignPossibleDuplicate(Owner owner, String normalizedTelephone, boolean sharesHousehold) {
598	        if (sharesHousehold) {
599	            owner.setPossibleDuplicateOf(null);
600	            owner.setPossibleDuplicate(false);
601	            return;
602	        }
603	        String postcode = owner.getPostcode();
604	        Integer matchId = null;
605	        if (postcode != null) {
606	            String lastName = normalizeForComparison(owner.getLastName());
607	            for (Owner existing : this.clinicService.findAllOwners()) {
608	                if (postcode.equals(existing.getPostcode())
609	                    && lastName.equals(normalizeForComparison(existing.getLastName()))
610	                    && !normalizedTelephone.equals(toE164OrNull(existing.getTelephone()))
611	                    && existing.getId() != null
612	                    && (matchId == null || existing.getId() < matchId)) {
613	                    matchId = existing.getId();
614	                }
615	            }
616	        }
617	        owner.setPossibleDuplicateOf(matchId);
618	        owner.setPossibleDuplicate(matchId != null);
619	    }
620	
621	    /**
622	     * The maximum number of owners a single city may contain. Once a city already holds this many
623	     * owners, creating another owner in that city is rejected.
624	     */
625	    private static final int MAX_OWNERS_PER_CITY = 50;
626	
627	    /**
628	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
629	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
630	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
631	     * counting used elsewhere.
632	     *
633	     * @param city the city of the owner being created
634	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
635	     */
636	    /**
637	     * The maximum number of owners that may be registered on a single day. Once this many owners
638	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
639	     */
640	    private static final int MAX_OWNERS_PER_DAY = 100;
641	
642	    /**
643	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
644	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
645	     * registration date of the owner being created.
646	     *
647	     * @param registrationDate the registration date of the owner being created
648	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
649	     */
650	    /**
651	     * Rolls an effective registration date forward onto a business day. A registration date must fall
652	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
653	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
654	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
655	     * count, the membership number's year segment, and so on) uses this adjusted date.
656	     *
657	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
658	     * @return the same date if it is a weekday, otherwise the following Monday
659	     */
660	    /**
661	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
662	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
663	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
664	     * against the date exactly as supplied, before it is rolled forward onto a business day.
665	     *
666	     * @param registrationDate the registration date supplied in the request, may be {@code null}
667	     * @throws FutureRegistrationDateException if the supplied date is after the server date
668	     */
669	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
670	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
671	            throw new FutureRegistrationDateException(registrationDate);
672	        }
673	    }
674	
675	    private LocalDate rollToBusinessDay(LocalDate date) {
676	        DayOfWeek day = date.getDayOfWeek();
677	        if (day == DayOfWeek.SATURDAY) {
678	            return date.plusDays(2);
679	        }
680	        if (day == DayOfWeek.SUNDAY) {
681	            return date.plusDays(1);
682	        }
683	        return date;
684	    }
685	
686	    private void rejectDailyLimitReached(LocalDate registrationDate) {
687	        long ownersToday = this.clinicService.findAllOwners().stream()
688	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
689	            .count();
690	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
691	            throw new DailyOwnerLimitExceededException(registrationDate);
692	        }
693	    }
694	
695	    /**
696	     * The number of owners that must already share a {@code registrationDate} before a newly created
697	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
698	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
699	     */
700	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
701	
702	    /**
703	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
704	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
705	     * the same registration date at the time this owner is created. Existing owners are counted by their
706	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
707	     * daily create-limit accumulation.
708	     *
709	     * @param registrationDate the registration date of the owner being created
710	     * @return {@code true} if the day already holds more than the threshold number of owners
711	     */
712	    private boolean isBulkSignupDay(LocalDate registrationDate) {
713	        long ownersToday = this.clinicService.findAllOwners().stream()
714	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
715	            .count();
716	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
717	    }
718	
719	    private void rejectCityAtCapacity(String city) {
720	        String normalizedCity = normalizeForComparison(city);
721	        long ownersInCity = this.clinicService.findAllOwners().stream()
722	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
723	            .count();
724	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
725	            throw new OwnerCityCapacityExceededException(city);
726	        }
727	    }
728	
729	    /**
730	     * Counts how many owners belong to the household the owner being created has just been assigned to,
731	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
732	     * given identifier; the owner being created is added on because it is counted before being persisted.
733	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
734	     * household of one. The value is snapshotted on the owner.
735	     *
736	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
737	     * @return the number of household members, including the owner being created
738	     */
739	    private int countHousehold(String householdId) {
740	        if (householdId == null) {
741	            return 1;
742	        }
743	        long existing = this.clinicService.findAllOwners().stream()
744	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
745	            .count();
746	        return (int) existing + 1;
747	    }
748	
749	    /**
750	     * Derives the deterministic household identifier for a given last name and postcode: the first 12
751	     * hex characters of the SHA-256 digest of {@code '<normalizedLastName>|<postcode>'}, where the last
752	     * name is normalized for case- and whitespace-insensitive comparison (see
753	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Every
754	     * owner that shares a last name and postcode therefore resolves to the exact same identifier,
755	     * regardless of creation order, making them members of one household.
756	     *
757	     * @param lastName the owner's last name
758	     * @param postcode the owner's postcode, may be {@code null}
759	     * @return the deterministic household identifier
760	     */
761	    private String householdId(String lastName, String postcode) {
762	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
763	        try {
764	            byte[] digest = MessageDigest.getInstance("SHA-256")
765	                .digest(key.getBytes(StandardCharsets.UTF_8));
766	            StringBuilder hex = new StringBuilder();
767	            for (int i = 0; i < 6; i++) {
768	                hex.append(String.format("%02x", digest[i]));
769	            }
770	            return hex.toString();
771	        } catch (NoSuchAlgorithmException ex) {
772	            throw new IllegalStateException("SHA-256 not available", ex);
773	        }
774	    }
775	
776	    /**
777	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
778	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
779	     * result is lower-cased. A {@code null} value normalizes to the empty string.
780	     *
781	     * @param value the value to normalize, may be {@code null}
782	     * @return the normalized value
783	     */
784	    private String normalizeForComparison(String value) {
785	        if (value == null) {
786	            return "";
787	        }
788	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
789	    }
790	
791	    /**
792	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
793	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
794	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
795	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
796	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
797	     * that is stored, returned, and used for every address comparison (household duplicate detection
798	     * and the shared household id).
799	     *
800	     * @param address the raw address value from the submitted owner payload, may be {@code null}
801	     * @return the normalized address
802	     */
803	    /**
804	     * Applies address normalization to the owner and derives the composed {@code address}, preferring
805	     * the structured fields over the flat {@code address} input for backward compatibility. When a
806	     * non-blank {@code addressLine1} is supplied, both structured lines are normalized (see
807	     * {@link #normalizeAddress}) and stored, and the composed {@code address} becomes the normalized
808	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
809	     * {@code addressLine2} was supplied. Otherwise the flat {@code address} is normalized and stored, and
810	     * the structured lines are cleared. The stored {@code address} is the form every later step reads.
811	     *
812	     * @param owner the owner being created, whose raw address fields are normalized in place
813	     */
814	    private void applyAddress(Owner owner) {
815	        String line1 = owner.getAddressLine1();
816	        if (line1 != null && !line1.isBlank()) {
817	            String normalizedLine1 = normalizeAddress(line1);
818	            String normalizedLine2 = normalizeAddress(owner.getAddressLine2());
819	            owner.setAddressLine1(normalizedLine1);
820	            if (!normalizedLine2.isEmpty()) {
821	                owner.setAddressLine2(normalizedLine2);
822	                owner.setAddress(normalizedLine1 + " " + normalizedLine2);
823	            } else {
824	                owner.setAddressLine2(null);
825	                owner.setAddress(normalizedLine1);
826	            }
827	        } else {
828	            owner.setAddressLine1(null);
829	            owner.setAddressLine2(null);
830	            owner.setAddress(normalizeAddress(owner.getAddress()));
831	        }
832	    }
833	
834	    private String normalizeAddress(String address) {
835	        if (address == null) {
836	            return "";
837	        }
838	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
839	        if (collapsed.isEmpty()) {
840	            return "";
841	        }
842	        String[] tokens = collapsed.split(" ");
843	        StringBuilder normalized = new StringBuilder();
844	        for (int i = 0; i < tokens.length; i++) {
845	            if (i > 0) {
846	                normalized.append(' ');
847	            }
848	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
849	        }
850	        return normalized.toString();
851	    }
852	}
